import{_ as n,a as t}from"./chunks/handle-2.CzNXFkXD.js";import{_ as e}from"./chunks/packing-8.DMWZiLEo.js";import{_ as i,o,c as r,a5 as s}from"./chunks/framework.CcrBcQWS.js";const k=JSON.parse('{"title":"Handling and Transportation","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"manual/safety/handling-and-transportation.md","filePath":"manual/safety/handling-and-transportation.md","lastUpdated":1787021357000}'),l={name:"manual/safety/handling-and-transportation.md"};function d(h,a,g,c,p,u){return o(),r("div",null,[...a[0]||(a[0]=[s('<h1 id="handling-and-transportation" tabindex="-1">Handling and Transportation <a class="header-anchor" href="#handling-and-transportation" aria-label="Permalink to &quot;Handling and Transportation&quot;">​</a></h1><p>Safe handling when moving, packing, and shipping the RBQ. Packing and unpacking steps are also on the <a href="/RBQ/nightly/manual/operation/packing.html">Packing</a> page.</p><h2 id="general-precautions-when-moving" tabindex="-1">General precautions when moving <a class="header-anchor" href="#general-precautions-when-moving" aria-label="Permalink to &quot;General precautions when moving&quot;">​</a></h2><ul><li><strong>Power off</strong>: <strong>Always turn power off</strong> before lifting or moving. If power is on, legs can move and cause injury.</li><li>The robot is heavy and joints can move-support it so it cannot fall, or use designated carriers/moving methods.</li></ul><h3 id="pinch-hazard-and-handles" tabindex="-1">Pinch hazard and handles <a class="header-anchor" href="#pinch-hazard-and-handles" aria-label="Permalink to &quot;Pinch hazard and handles&quot;">​</a></h3><ul><li>Keep <strong>fingers, clothing, long hair, and jewelry</strong> out of handle and joint areas. Grip handles with a <strong>closed fist</strong>; do not insert fingers where they can be pinched.</li></ul><figure><img src="'+n+'" alt="Correct grip on handle with closed fist" style="max-width:100%;width:min(420px, 100%);display:block;margin:0 auto;"><figcaption style="text-align:center;">[ Grip handles with a closed fist so fingers cannot be pinched. ]</figcaption></figure><h3 id="lifting" tabindex="-1">Lifting <a class="header-anchor" href="#lifting" aria-label="Permalink to &quot;Lifting&quot;">​</a></h3><ul><li><strong>Two people required</strong>: Always lift with <strong>two people</strong> front and back. <strong>With one hand support the left/right legs (or body side)</strong>; <strong>with the other hand grip the handle in a fist</strong>. <strong>Lift using the handle</strong> so the whole robot stays level and stable. Lifting from one side only or twisting can drop legs or shift the center of mass.</li><li>The RBQ is <strong>modular</strong>. Unlike a single-piece body, <strong>parts can separate and fall</strong> more easily. Avoid shock and twisting when lifting; do not drop-coordinate and move slowly.</li></ul><figure><img src="'+t+'" alt="Two-person lift front and back" style="max-width:100%;width:min(420px, 100%);display:block;margin:0 auto;"><figcaption style="text-align:center;">[ One hand supports left/right legs; the other grips the handle-lift by the handle and move the whole robot steadily. ]</figcaption></figure><div class="sb sb-warning"><div class="sb-icon"><span class="sb-warn" aria-hidden="true">⚠</span></div><div class="sb-content"><p class="custom-block-title">WARNING</p><p>Do not force-lift or drag while power is on. Turn power off and secure a stable posture first. Modular construction is more vulnerable to separation and drops than a one-piece design-take extra care against shock and drops.</p></div></div><h2 id="packing-and-shipping" tabindex="-1">Packing and shipping <a class="header-anchor" href="#packing-and-shipping" aria-label="Permalink to &quot;Packing and shipping&quot;">​</a></h2><figure><img src="'+e+'" alt="Robot packed and secured in box"><figcaption style="text-align:center;">[ Ship in original packaging and secure so nothing moves inside the box. ]</figcaption></figure><ul><li><strong>Original packaging</strong>: Use the factory packaging when possible-shock and vibration can damage internal parts.</li><li><strong>Securing</strong>: Cushion and secure so the robot cannot move inside the box.</li><li><strong>Labeling</strong>: Mark handling (orientation, fragile, etc.) and avoid excessive stacking or throwing.</li></ul><h2 id="battery" tabindex="-1">Battery <a class="header-anchor" href="#battery" aria-label="Permalink to &quot;Battery&quot;">​</a></h2><div class="sb sb-note"><div class="sb-icon"><span class="sb-note-i" aria-hidden="true">i</span></div><div class="sb-content"><p class="custom-block-title">NOTE</p><p>For air or sea shipment with the battery installed, check applicable rules (e.g. UN dangerous goods, airline rules). If required, remove the battery and ship separately-confirm in the manual or with Rainbow Robotics.</p></div></div><h2 id="docking-station-and-charger" tabindex="-1">Docking station and charger <a class="header-anchor" href="#docking-station-and-charger" aria-label="Permalink to &quot;Docking station and charger&quot;">​</a></h2><ul><li><strong>Charger and docking station</strong>: Pack and ship without shock; avoid tangling or crushing cables.</li></ul><h2 id="storage" tabindex="-1">Storage <a class="header-anchor" href="#storage" aria-label="Permalink to &quot;Storage&quot;">​</a></h2><ul><li><strong>When not in use</strong>: Store in the <strong>dedicated case</strong> or <strong>docking station</strong> when possible. Case size and weight are in the product documentation.</li><li><strong>Environment</strong>: Follow <strong>storage temperature and humidity</strong> in <a href="/RBQ/nightly/manual/safety/operating-environment-requirements.html">Operating Environment Requirements</a>. For the battery, follow <a href="/RBQ/nightly/manual/safety/battery-handling.html">Battery Handling Precautions</a>.</li></ul>',20)])])}const w=i(l,[["render",d]]);export{k as __pageData,w as default};
